/**
 * @method
 * @name setCodes
 * @description set Codes 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCodes = async function() {
    const sbmOptions = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 지정자문인 콤보박스 로딩
    const sbmOptions3 = {
        id : "sbm_dts_Design_Adviser",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Design_Adviser=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions4 = {
        id : "sbm_dts_Delete",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Delete=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const vMARKET_FLAG = rdo_MARKET_FLAG.getValue();
    const vDEP_CD = cmb_DEP_CD.getValue();
    let vISUR_CD = txb_ISUR_CD.getValue();
    const vEMP_NO = cmb_EMP_NO.getValue();
    const vLIST_STATUS = cmb_LIST_STATUS.getValue();
    const vDESIGN_ADVSER_ISUR_CD = cmb_Design_advise.getValue();
    if (vMARKET_FLAG === "" && vDEP_CD === "" && vISUR_CD === "" && vEMP_NO === "") {
        await $c.win.alert("[검색조건]을 하나이상 선택하세요.");
        return;
    }
    let secuGrpId = "";
    if (chb_Grp_St.getValue() === 'Y') secuGrpId += 'ST,';
    if (chb_Grp_Mf.getValue() === 'Y') secuGrpId += 'MF,';
    if (chb_Grp_Rt.getValue() === 'Y') secuGrpId += 'RT,';
    if (chb_Grp_Sc.getValue() === 'Y') secuGrpId += 'SC,';
    if (chb_Grp_Fs.getValue() === 'Y') secuGrpId += 'FS,';
    if (chb_Grp_Dr.getValue() === 'Y') secuGrpId += 'DR,';
    if (chb_Grp_If.getValue() === 'Y') secuGrpId += 'IF,';
    if (chb_Grp_All.getValue() === ' Y') secuGrpId = '';
    url += "&MARKET_FLAG=" + vMARKET_FLAG;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&EMP_NO=" + vEMP_NO;
    // url += "&ATTR_TP_CD=" + vATTR_TP_CD; //회사속성
    url += "&LIST_STATUS=" + vLIST_STATUS;
    url += "&SECU_GRP_ID=" + secuGrpId;
    url += "&DESIGN_ADVSER_ISUR_CD=" + vDESIGN_ADVSER_ISUR_CD;
    url += "&SCREN_ID=" + "ULDSTF30660.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    if (dts_Grid.getRowCount() > 0) {
        await scwin.readChargeIssue(grd_List, 1, "ISUR_CD");
    } else {
        dts_Corp_Info.removeAll();
        dts_Krx_Emp_Info.removeAll();
        dts_Charge1_Info.removeAll();
        dts_Charge2_Info.removeAll();
        dts_Charge3_Info.removeAll();
        dts_Advisor_Info.removeAll(); // 20220624 추가
        dts_AdvisorList.removeAll(); // 20220624 추가

    }
};

