/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {*} gbn gbn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(gbn) {
    let txb_Chrg_Chrg_Tp_Cd_value;
    let txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value;
    let txb_Chrg_CHRG_NM_value;
    let txb_Chrg_JOBTITL_NM_value;
    let del_msg;
    if (gbn === "2") {
        txb_Chrg_Chrg_Tp_Cd_value = txb_Chrg2_Chrg_Tp_Cd.getValue();
        txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value = txb_Chrg2_Discls_Bz_Chrg_Assgn_Dd.getValue();
        txb_Chrg_CHRG_NM_value = txb_Chrg3_CHRG_NM.getValue();
        txb_Chrg_JOBTITL_NM_value = txb_Chrg3_JOBTITL_NM.getValue();
        del_msg = "공시담당자 ";
    } else if (gbn === "3") {
        txb_Chrg_Chrg_Tp_Cd_value = txb_Chrg3_Chrg_Tp_Cd.getValue();
        txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value = txb_Chrg3_Discls_Bz_Chrg_Assgn_Dd.getValue();
        txb_Chrg_CHRG_NM_value = txb_Chrg2_CHRG_NM.getValue();
        txb_Chrg_JOBTITL_NM_value = txb_Chrg2_JOBTITL_NM.getValue();
        del_msg = "공시 실무자 ";
    }
    del_msg += txb_Chrg_CHRG_NM_value + " " + txb_Chrg_JOBTITL_NM_value + " 님을";

    // alert(gIsurCd + "_" + txb_Chrg_Chrg_Tp_Cd_value + "_" + txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value + "...");

    const res = window.confirm(del_msg + " 삭제하시겠습니까?");
    if (res) {
        dts_Delete.removeAll();
        dts_Delete.insertRow();
        dts_Delete.setCellData(1, "ISUR_CD", scwin.gIsurCd);
        dts_Delete.setCellData(1, "CHRG_TP_CD", txb_Chrg_Chrg_Tp_Cd_value);
        dts_Delete.setCellData(1, "DISCLS_BZ_CHRG_ASSGN_DD", txb_Chrg_Discls_Bz_Chrg_Assgn_Dd_value);
        dts_Delete.setCellData(1, "TRANSTR_EMP_NO", scwin.gEmpNo);
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedCompany.do",
            ref : "dts_Delete",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");
    return (arr.length >= 1 ? $c.frame.path("../" + arr[1]) : undefined);
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParentValue = async function() {
    const pvd = scwin.getProvider();
    if (pvd !== null) {
        scwin.gMktTp = pvd.scwin.gMktTp;
        scwin.gIsurCd = pvd.scwin.gIsurCd;
        if ($c.ut.trim(scwin.gIsurCd).length === 5) {
            await scwin.initSearch();
        }
    }
};

/**
 * @method
 * @name initSearch
 * @description 다른창에서 담당종목 조회를 클릭할때
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initSearch = async function() {
    await scwin.getChargeIssue(scwin.gIsurCd, scwin.gMktTp);
};

/**
 * @method
 * @name readChargeIssue
 * @description read Charge Issue 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readChargeIssue = async function(GridID, row, colid) {
    if (row < 1) return;
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    let vISUR_CD = objDataID.getCellData(row, "ISUR_CD");
    scwin.gIsurCd = vISUR_CD; // 20180802
    const vMKT_TP_CD = objDataID.getCellData(row, "SPOT_ISU_TRD_MKT_TP_CD");
    scwin.gSelectedLdMktTpCd = vMKT_TP_CD; // 20180802

    await scwin.getChargeIssue(vISUR_CD, vMKT_TP_CD);
};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
    panel_mkt.hide();
};

/**
 * @method
 * @name changeFormat
 * @description change Format 처리
 * @returns {void}
 * @hidden N
 */
scwin.changeFormat = function() {
    const ar = new Array(txb_Corp_RGHT_LIST_DD, txb_Chrg1_EDU_COMPLT_DD, txb_Chrg1_CHRG_DESIGN_DD, txb_Chrg1_BIRTHDD, txb_Chrg1_WORK_TM, txb_Chrg2_WORK_TM, txb_Chrg3_WORK_TM, txb_Chrg2_EDU_COMPLT_DD, txb_Chrg2_CHRG_DESIGN_DD, txb_Chrg2_BIRTHDD, txb_Chrg3_EDU_COMPLT_DD, txb_Chrg3_CHRG_DESIGN_DD, txb_Chrg3_BIRTHDD);
    for (let i = 0; i < ar.length; i++) {
        const bfVal = ar[i].getValue();
        if (bfVal !== "") {
            const afVal = $c.stf.FormatDateEx(bfVal);
            ar[i].setValue(afVal);
        }
    }
};

/**
 * @method
 * @name FormatDateEx
 * @description Format Date Ex 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.FormatDateEx = function(str) {
    if (str === "") return "";
    return str.substring(0, 4) + "-" + str.substring(4, 6) + "-" + str.substring(6, 8);
};

/**
 * @method
 * @name allCheck
 * @description all Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.allCheck = function() {
    const checkArray = [chb_Grp_St, chb_Grp_Mf, chb_Grp_Sc, chb_Grp_Rt, chb_Grp_Dr, chb_Grp_Fs, chb_Grp_If];
    if (chb_Grp_All.checked === true) {
        for (let i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
